import {scenarios,rules,generateScenario,scoreSession,severity,metrics,findings,trace,reportFor,inspectCapture} from './engine.js';
const paths={shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7l-9-4Z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',activity:'M3 12h4l3-8 4 16 3-8h4',layers:'m12 3 10 6-10 6L2 9l10-6Z M2 13l10 6 10-6 M2 17l10 6 10-6',alert:'m12 3 10 18H2L12 3Z M12 9v5 M12 17v1',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',play:'m8 4 12 8-12 8V4Z',arrow:'M4 12h16 M14 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',check:'M5 12l4 4L19 6',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',close:'m6 6 12 12 M18 6 6 18',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',chevron:'m9 5 7 7-7 7',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 14 1 M19 17A8 8 0 0 1 5 16'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={page:'Overview',scenario:'enterprise',sessions:generateScenario(),selected:'enterprise',busy:false,step:0,logs:[],filter:'All',protocol:'All',query:'',fixes:[],capture:null};
const nav=[['Overview','grid'],['Capture analysis','layers'],['Sessions','activity'],['Findings','alert'],['Simulation lab','play'],['Reports','file']];
const badge=(text,type=text.toLowerCase())=>`<span class="badge ${type}">${esc(text)}</span>`;
function go(page){state.page=page;state.filter='All';state.protocol='All';state.query='';render();window.scrollTo(0,0);}
function header(title,sub,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function render(){const m=metrics(state.sessions);document.getElementById('app').innerHTML=`<div class="layout"><aside><div class="brand">${icon('shield',30)}<div>SecureMailScope<small>CRYPTOGRAPHIC INTELLIGENCE</small></div></div><div class="navlabel">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([n,i])=>`<button data-nav="${n}" class="${state.page===n?'active':''}" ${state.page===n?'aria-current="page"':''}>${icon(i)}${n}${n==='Findings'?`<span class="count">${m.findings}</span>`:''}</button>`).join('')}</nav><div class="sidebottom"><div class="offline"><strong>${icon('lock',14)} &nbsp; Local analysis</strong><br><span class="muted">Your captures stay on this device.</span></div><div class="profile"><div class="avatar">CP</div><div>Crypterpillars<small>SIH 2026 · PS 26159</small></div></div></div></aside><main class="main"><div class="topbar"><span>Workspace &nbsp; / &nbsp; <strong>${state.page}</strong></span><span class="badge">${icon('play',12)} INTERACTIVE DEMO</span></div><div class="content">${pageContent()}<div class="footnote"><span>${icon('shield',13)} SecureMailScope · Passive email security assessment</span><span>Synthetic evidence · Rules-based demonstration</span></div></div></main></div>`;bind();}
function captureBanner(){return `<div class="capture"><div class="fileicon">${icon('file',23)}</div><div><strong>${scenarios[state.scenario].file}</strong><div class="meta">Synthetic capture &nbsp; · &nbsp; 19 Sep 2026, 10:00 UTC &nbsp; · &nbsp; ${metrics(state.sessions).packets.toLocaleString()} fixture packets</div></div><div class="right">${badge(state.fixes.length?'Remediated simulation':'Analysis complete')}<button class="textbutton" data-nav="Capture analysis">Change capture ${icon('chevron',14)}</button></div></div>`;}
function pageContent(){switch(state.page){case 'Overview':return overview();case 'Sessions':return sessionsPage();case 'Findings':return findingsPage();case 'Simulation lab':return simulationPage();case 'Capture analysis':return capturePage();case 'Reports':return reportsPage();}}
function overview(){const ss=state.sessions,m=metrics(ss),groups=findings(ss),weak=ss.filter(s=>['TLS 1.0','TLS 1.1'].includes(s.tls)).length;return header('Security overview','Understand the cryptographic posture of your email infrastructure.',`<button data-action="export-json">${icon('download',16)} &nbsp; Export report</button><button class="primary" data-nav="Simulation lab">${icon('play',16)} &nbsp; Run simulation</button>`)+captureBanner()+`<div class="stats"><div class="stat"><div class="statlabel">Sessions analyzed ${icon('layers',17)}</div><div class="statvalue">${ss.length}<span style="font-size:13px;color:var(--muted);font-weight:400;letter-spacing:0"> &nbsp; across ${new Set(ss.map(s=>s.protocol)).size} protocols</span></div><div class="statfoot"><b>${ss.length-ss.filter(s=>s.issues.includes('partial')).length} complete</b> · ${ss.filter(s=>s.issues.includes('partial')).length} partial</div></div><div class="stat"><div class="statlabel">Encrypted sessions ${icon('lock',17)}</div><div class="statvalue">${Math.round(m.encrypted/ss.length*100)}<span style="font-size:20px">%</span></div><div class="statfoot">${m.encrypted} of ${ss.length} sessions negotiated TLS</div></div><div class="stat"><div class="statlabel">Security findings ${icon('alert',17)}</div><div class="statvalue" style="color:var(--amber)">${m.findings}</div><div class="statfoot">${groups.length} distinct weakness types</div></div><div class="stat"><div class="statlabel">Critical sessions ${icon('activity',17)}</div><div class="statvalue" style="color:var(--red)">${m.critical.toString().padStart(2,'0')}</div><div class="statfoot">${m.critical?'Immediate attention recommended':'No critical risks in this scenario'}</div></div></div><div class="grid"><section class="panel"><div class="panelhead"><h2>Security posture</h2><small>ⓘ</small></div><div class="panelbody"><div class="gauge" style="--score:${m.score}"><div class="value"><b>${m.score??'—'}</b><small>OUT OF 100</small></div></div><div class="gaugecaption">${m.score>=90?'Strong posture':m.score>=75?'Acceptable · improvements available':m.score>=50?'Weak · action required':'High risk · action required'}</div><div class="scorefoot"><span>Deterministic assessment</span><button class="textbutton" data-action="score-info">View scoring ${icon('chevron',12)}</button></div></div></section><section class="panel"><div class="panelhead"><h2>TLS distribution</h2><small>Sessions</small></div><div class="panelbody">${['TLS 1.3','TLS 1.2','TLS 1.1','TLS 1.0'].map((t,i)=>{const n=ss.filter(s=>s.tls===t).length;return `<div class="barrow"><div class="barlabel"><button class="textbutton" style="color:inherit" data-tls="${t}">${t}</button><span>${n} <span class="muted">/ ${ss.length}</span></span></div><div class="bar"><i style="width:${n/ss.length*100}%;background:${['#73e6bc','#659dec','#eeb96b','#fb8189'][i]}"></i></div></div>`}).join('')}<div class="tlssummary">${weak} legacy sessions · ${ss.filter(s=>s.tls==='None').length} plaintext · ${ss.filter(s=>s.tls==='Unknown').length} unknown</div></div></section><section class="panel"><div class="panelhead"><h2>Email protocols</h2><small>Coverage</small></div><div class="panelbody"><svg width="100%" height="139" viewBox="0 0 260 139" role="img" aria-label="Protocol distribution"><path d="M45 123a85 85 0 0 1 170 0" stroke="#25313a" stroke-width="27" fill="none"/>${['SMTP','IMAP','POP3'].map((p,i,ps)=>{const n=ss.filter(s=>s.protocol===p).length/ss.length*100;const offset=ps.slice(0,i).reduce((a,p)=>a+ss.filter(s=>s.protocol===p).length/ss.length*100,0);return `<path d="M45 123a85 85 0 0 1 170 0" pathLength="100" stroke="${['#73e6bc','#659dec','#ad9ceb'][i]}" stroke-width="27" fill="none" stroke-dasharray="${n} ${100-n}" stroke-dashoffset="${-offset}"/>`}).join('')}<text x="130" y="103" text-anchor="middle" fill="#e2e8ef" font-size="30" font-family="Manrope">${ss.length}</text><text x="130" y="123" text-anchor="middle" fill="#87929f" font-size="11">TOTAL SESSIONS</text></svg>${['SMTP','IMAP','POP3'].map((p,i)=>`<div class="barlabel" style="margin:15px 0 0"><span><i style="display:inline-block;width:7px;height:7px;background:${['#73e6bc','#659dec','#ad9ceb'][i]};border-radius:2px;margin-right:7px"></i>${p}</span><span>${ss.filter(s=>s.protocol===p).length} <span class="muted">sessions</span></span></div>`).join('')}</div></section></div><div class="twocol"><section class="panel"><div class="panelhead"><h2>Priority findings <span class="muted" style="font-weight:400">&nbsp; ${groups.length}</span></h2><button class="textbutton" data-nav="Findings">View all ${icon('arrow',14)}</button></div>${groups.length?`<div class="tablewrap"><table><thead><tr><th>Finding</th><th>Severity</th><th>Sessions</th><th></th></tr></thead><tbody>${groups.slice(0,4).map(f=>`<tr class="clickable" data-session="${f.sessions[0].id}"><td>${f.title}<small>${f.key.toUpperCase()} · Packet-linked evidence</small></td><td>${badge(f.severity)}</td><td>${f.sessions.length.toString().padStart(2,'0')}</td><td>${icon('chevron',14)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No weaknesses detected in this synthetic scenario.</div>'}</section><section class="panel"><div class="panelhead"><h2>${icon('spark',18)} &nbsp; Analyst insights</h2>${badge('EXPLAINABLE','low')}</div><div class="panelbody"><div class="insight">${icon('alert',18)}<div><strong>${weak?'Encryption does not equal security':'Modern encryption baseline'}</strong><p>${weak?`${weak} sessions negotiated legacy TLS. ${ss.filter(s=>s.issues.includes('pfs')).length} sessions lack forward secrecy.`:'All observed negotiated versions meet the modern protocol baseline in this scenario.'}</p></div></div><div class="insight">${icon('activity',18)}<div><strong>${ss.some(s=>s.issues.includes('downgrade'))?'Capability change detected':'No downgrade indicators'}</strong><p>${ss.some(s=>s.issues.includes('downgrade'))?'STARTTLS disappears from the synthetic server baseline. Review the transition and authentication sequence.':'No STARTTLS capability regression appears in the synthetic evidence.'}</p></div></div><button class="textbutton" data-nav="Simulation lab">Explore the evidence in the lab ${icon('arrow',14)}</button></div></section></div>`;}
function filteredSessions(){return state.sessions.filter(s=>(state.filter==='All'||s.tls===state.filter||severity(s)===state.filter)&&(state.protocol==='All'||s.protocol===state.protocol)&&`${s.id} ${s.server} ${s.client}`.toLowerCase().includes(state.query.toLowerCase()));}
function sessionRows(){const rows=filteredSessions();return rows.length?rows.map(s=>`<tr class="clickable" data-session="${s.id}"><td><button class="textbutton" data-session="${s.id}">${s.id}</button><small>${s.time} UTC</small></td><td>${s.server}<small>${s.client} → :${s.port}</small></td><td>${s.protocol}</td><td>${s.tls}</td><td>${s.pfs}</td><td>${badge(severity(s))}</td><td>${s.issues.includes('partial')?'—':scoreSession(s)} ${icon('chevron',13)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No sessions match these filters.</td></tr>';}
function sessionsPage(){return header('Session explorer','Reconstruct each connection, verify the handshake, and follow its evidence.',`<button data-action="export-json">${icon('download',16)} &nbsp; Export evidence</button>`)+`<div class="toolbar"><input type="search" id="session-search" aria-label="Search sessions" placeholder="Search server, IP, or session ID…" value="${esc(state.query)}"><select id="protocol-filter" aria-label="Filter protocol">${['All','SMTP','IMAP','POP3'].map(x=>`<option ${state.protocol===x?'selected':''}>${x}</option>`)}</select><select id="risk-filter" aria-label="Filter risk or TLS version">${['All','Critical','High','Medium','Low','Unknown','TLS 1.3','TLS 1.2','TLS 1.1','TLS 1.0','None'].map(x=>`<option ${state.filter===x?'selected':''}>${x}</option>`)}</select><button data-action="clear-filters">Reset filters</button></div><section class="panel"><div class="panelhead"><h2>Reconstructed sessions</h2><small id="result-count">${filteredSessions().length} matching sessions</small></div><div class="tablewrap"><table><thead><tr><th>Session</th><th>Endpoint</th><th>Protocol</th><th>Negotiated TLS</th><th>Forward secrecy</th><th>Risk</th><th>Score</th></tr></thead><tbody id="session-rows">${sessionRows()}</tbody></table></div></section>`;}
function findingsPage(){const ff=findings(state.sessions);const filtered=ff.filter(f=>state.filter==='All'||f.severity===state.filter);return header('Findings & remediation','Evidence-backed recommendations, ordered by cryptographic risk.',`<button class="primary" data-action="fix-all" ${!ff.some(f=>f.weight)?'disabled':''}>${icon('check',16)} &nbsp; Simulate all fixes</button>`)+`<div class="notice">Remediation changes the simulated configuration only. No servers are contacted or modified. Re-capturing a partial handshake is a separate evidence task.</div><div class="toolbar">${['All','Critical','High','Medium','Informational'].map(x=>`<button class="${state.filter===x?'primary':''}" data-severity="${x}">${x}</button>`).join('')}</div>${filtered.length?filtered.map(f=>`<section class="panel remediate"><div>${icon(f.severity==='Informational'?'file':'alert',23)}</div><div style="flex:1"><h3>${f.title} &nbsp; ${badge(f.severity)}</h3><p>${f.reason}</p><p><strong style="color:#dce3eb">${f.action}</strong></p><span class="muted" style="font-size:12px">${f.sessions.length} affected sessions · ${f.weight?f.weight+' score-point penalty per session':'Not scored: incomplete evidence'}</span></div><div class="actions"><button data-session="${f.sessions[0].id}">Evidence</button>${f.weight?`<button class="primary" data-fix="${f.key}">Simulate fix</button>`:''}</div></section>`).join(''):'<div class="panel empty">No findings in this category.</div>'}${state.fixes.length?`<div class="notice">${state.fixes.length} remediation rules applied to this simulation. <button class="textbutton" data-action="reset">Reset scenario</button></div>`:''}`;}
function simulationPage(){const base=metrics(generateScenario(state.scenario)).score,now=metrics(state.sessions).score;return header('Simulation lab','Walk through the journey from captured packets to an actionable security decision.',`<button data-action="reset" ${state.busy?'disabled':''}>${icon('refresh',16)} &nbsp; Reset scenario</button>`)+`<div class="cards">${Object.entries(scenarios).map(([key,s])=>`<section class="panel scenario ${state.selected===key?'selected':''}">${icon(key==='secure'?'shield':key==='downgrade'?'alert':'layers',28)}<h2>${s.name}</h2><p>${s.description}</p><div class="muted" style="font-size:12px">${s.count} synthetic sessions · SMTP / IMAP / POP3</div><button data-scenario="${key}" class="${state.selected===key?'primary':''}" ${state.busy?'disabled':''}>${state.selected===key?'Selected scenario':'Select scenario'}</button></section>`).join('')}</div><section class="panel lab"><div class="heading"><div><h2>Packet-to-posture pipeline</h2><p style="margin-top:8px">A guided replay of deterministic synthetic evidence.</p></div><button class="primary" data-action="run" ${state.busy?'disabled':''}>${icon('play',16)} &nbsp; ${state.busy?'Analyzing…':'Run simulation'}</button></div><div class="pipeline">${['Capture intake','Reconstruct sessions','Inspect TLS & X.509','Evaluate risk','Generate report'].map((x,i)=>`<div class="step ${state.step>i?'done':''}">${state.step>i?'✓':String(i+1).padStart(2,'0')} &nbsp; ${x}</div>`).join('')}</div><div class="terminal" aria-live="polite">${state.logs.length?state.logs.map(esc).join('\n'):'> Select a scenario and run the simulation.\n> Synthetic packet evidence is processed entirely in your browser.\n> No credentials, live connections, or trained model are required.'}</div><div class="progress"><i style="width:${state.step*20}%"></i></div>${state.step===5?`<div class="actions" style="margin-top:20px"><button class="primary" data-nav="Overview">View assessment ${icon('arrow',16)}</button><button data-session="${state.sessions[0].id}">Inspect first session</button><button data-nav="Findings">Explore remediation</button></div>`:''}</section><section class="panel lab"><div class="heading"><div><h2>What changes after remediation?</h2><p style="margin-top:7px">Compare the loaded scenario against the simulated fixes.</p></div><div class="compare"><div><span>Before</span><br><strong>${base}</strong></div>${icon('arrow',24)}<div><span>After</span><br><strong style="color:var(--green)">${now}</strong></div></div></div><button data-nav="Findings">Open remediation workspace ${icon('arrow',16)}</button></section><div class="notice">AI-assisted workflow demonstration: explanations are produced by transparent rules on fixture features. No trained classifier or measured model accuracy is claimed. TLS 1.3 certificate details come from lab ground truth, since those handshake messages are encrypted.</div>`;}
function capturePage(){return header('Capture analysis','Load a reproducible demo or validate the structure of your own capture.')+`<div class="cards">${Object.entries(scenarios).map(([k,s])=>`<section class="panel scenario">${icon('file',26)}<h2>${s.name}</h2><p>${s.description}</p><button class="primary" data-load="${k}" ${state.busy?'disabled':''}>Load demonstration ${icon('arrow',15)}</button></section>`).join('')}</div><section class="upload">${icon('upload',32)}<h2 style="margin-top:14px">Inspect a PCAP or PCAPNG file</h2><p class="muted">File validation, packet count, and SHA-256 integrity hash · Up to 50 MB</p><input id="capture-file" type="file" accept=".pcap,.pcapng" aria-label="Select PCAP or PCAPNG capture"><p style="font-size:13px;color:var(--muted)">Local inspection only. This demo does not reconstruct TLS or score uploaded network traffic.</p></section>${state.capture?`<section class="panel lab"><h2>Capture intake result</h2><div class="detailgrid">${Object.entries(state.capture).map(([k,v])=>`<div class="detailitem"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="notice">Structural validation is complete. Security posture remains unassessed; use a synthetic scenario to demonstrate the analysis pipeline.</div></section>`:''}<div class="notice">Uploaded captures never leave your browser. The synthetic assessment is separate from uploaded file metadata and will not be presented as a real analysis result.</div>`;}
function reportsPage(){return header('Forensic reports','Export a reproducible record of the current scenario and remediation state.')+captureBanner()+`<div class="cards"><section class="panel reportcard">${icon('file',28)}<h2 style="margin-top:17px">Structured evidence</h2><p>Full session inventory, rule findings, scoring method, and simulation provenance.</p><button class="primary" data-action="export-json">${icon('download',16)} &nbsp; Download JSON</button></section><section class="panel reportcard">${icon('layers',28)}<h2 style="margin-top:17px">Analyst report</h2><p>A self-contained HTML report with prioritized remediation and a session appendix.</p><button class="primary" data-action="export-html">${icon('download',16)} &nbsp; Download HTML</button></section><section class="panel reportcard">${icon('file',28)}<h2 style="margin-top:17px">Print-ready report</h2><p>Open the formatted forensic report and choose “Save as PDF” in your browser’s print dialog.</p><button class="primary" data-action="print">${icon('file',16)} &nbsp; Print / Save PDF</button></section></div><section class="panel lab"><h2>Report provenance</h2><div class="detailgrid"><div class="detailitem"><small>Evidence source</small><strong>Deterministic synthetic fixture</strong></div><div class="detailitem"><small>Engine</small><strong>SecureMailScope Demo 1.0 · Rules-based</strong></div><div class="detailitem"><small>Assessment</small><strong>${state.fixes.length?'After simulated remediation':'Original scenario'}</strong></div><div class="detailitem"><small>Finding instances</small><strong>${metrics(state.sessions).findings}</strong></div></div><p class="muted" style="font-size:14px">Exports contain synthetic session metadata, not uploaded packet bytes. The JSON report includes a SHA-256 hash of its evidence payload for integrity verification.</p></section>`;}
function openSession(id){const s=state.sessions.find(s=>s.id===id);if(!s)return;showDrawer(`<div class="heading"><div><span class="muted" style="font-size:12px">SYNTHETIC SESSION EVIDENCE</span><h1 style="margin-top:8px">${s.id} · ${s.protocol}</h1><p>${s.server}</p></div><button data-close aria-label="Close session detail">${icon('close')}</button></div>${badge(severity(s))} &nbsp; ${badge(s.issues.includes('partial')?'Partial evidence':'Complete fixture','unknown')}<div class="detailgrid">${Object.entries({'Client':s.client,'Service port':s.port,'Negotiated protocol':s.tls,'Cipher suite':s.cipher,'Forward secrecy':s.pfs,'Certificate':s.cert,'Posture score':s.issues.includes('partial')?'Not assessed':scoreSession(s)+'/100','Evidence origin':'Synthetic lab fixture'}).map(([k,v])=>`<div class="detailitem"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3>Connection reconstruction</h3><div class="timeline">${trace(s).map(([f,title,body])=>`<div class="event"><small>Frame ${f} · ${title}</small><code>${esc(body)}</code></div>`).join('')}</div><h3>Explainable assessment</h3>${s.issues.length?s.issues.map(k=>`<div class="finding"><strong>${rules[k].title}</strong><p>${rules[k].reason}</p><span>${rules[k].action}</span></div>`).join(''):'<div class="notice">No configured risk rules triggered. This means the synthetic features meet this demo’s baseline, not that an actual endpoint has been verified.</div>'}<h3 style="margin-top:23px">X.509 fixture context</h3><div class="detailgrid"><div class="detailitem"><small>Subject / SAN</small><strong>${s.cert==='SAN mismatch'?'unrelated.example.org':s.server}</strong></div><div class="detailitem"><small>Validity at capture time</small><strong>${s.cert==='Expired'?'Expired 01 Sep 2026':s.tls==='None'||s.tls==='Unknown'?'Not observed':'Lab interval: 01 Jan – 31 Dec 2026'}</strong></div></div><p class="muted" style="font-size:13px">Certificate attributes are synthetic ground truth. Trust-chain and revocation validation are not performed. Encrypted email content is never decrypted.</p>`);}
let lastFocus;function showDrawer(html){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modalback"><section class="drawer" role="dialog" aria-modal="true" aria-label="Evidence details">${html}</section></div>`;document.body.style.overflow='hidden';document.querySelector('[data-close]')?.focus();document.querySelectorAll('[data-close]').forEach(el=>el.onclick=closeDrawer);document.querySelector('.modalback').onclick=e=>{if(e.target.classList.contains('modalback'))closeDrawer();};}
function closeDrawer(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
document.addEventListener('keydown',e=>{if(!document.querySelector('.drawer'))return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const els=[...document.querySelectorAll('.drawer button,.drawer a,.drawer input')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4500);}
function applyFix(key){const affected=state.sessions.filter(s=>s.issues.includes(key));if(!affected.length)return;for(const s of affected){s.issues=s.issues.filter(k=>k!==key);if(key==='legacy')s.tls='TLS 1.2';if(key==='expired'||key==='mismatch')s.cert='Valid fixture';if(key==='pfs'){s.pfs='Yes';s.cipher='TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384';}if(key==='cleartext'){s.port=s.protocol==='SMTP'?465:s.protocol==='IMAP'?993:995;s.tls='TLS 1.3';s.cipher='TLS_AES_256_GCM_SHA384';s.pfs='Yes';s.cert='Encrypted / fixture metadata';}}state.fixes.push(key);}
async function runSimulation(){if(state.busy)return;state.busy=true;state.step=0;state.logs=[];state.page='Simulation lab';const key=state.selected;render();const logs=[`[INTAKE] Loaded ${scenarios[key].file} • synthetic fixture validated`,`[STREAM] Reconstructed ${scenarios[key].count} SMTP / IMAP / POP3 sessions`,`[CRYPTO] Correlated STARTTLS transitions, negotiated ciphers, and lab certificate metadata`,`[RULES] Applied ${Object.keys(rules).length} explainable risk rules; no trained AI inference`,`[REPORT] Assessment complete. Evidence and recommendations ready.`];for(let i=0;i<5;i++){await new Promise(r=>setTimeout(r,650));state.step=i+1;state.logs.push(logs[i]);if(i===4){state.scenario=key;state.sessions=generateScenario(key);state.fixes=[];state.busy=false;}render();}toast('Simulation complete — explore the assessment.');}
async function hash(data){const b=typeof data==='string'?new TextEncoder().encode(data):data;return [...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');}
async function report(){const r=reportFor(state.sessions,state.scenario,!!state.fixes.length);r.evidenceSha256=await hash(JSON.stringify(r.sessions));r.hashScope='UTF-8 JSON.stringify(sessions), preserving property order';return r;}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function reportHtml(r){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>SecureMailScope forensic report</title><style>body{font:14px/1.6 Arial;color:#172537;max-width:1000px;margin:40px auto;padding:20px}h1{color:#126347}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #ccd6dc;text-align:left;padding:8px}small{overflow-wrap:anywhere}section{break-inside:avoid}button{padding:10px;background:#126347;color:white;border:0;border-radius:4px}@media print{button{display:none}body{margin:0}tr{break-inside:avoid}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>SecureMailScope</h1><h2>Cryptographic posture assessment</h2><p><strong>SIMULATED EVIDENCE — ${esc(r.scenario)}</strong><br>${r.remediated?'After simulated remediation':'Original fixture'} · ${esc(r.generatedAt)}</p><p>Posture: <strong>${r.metrics.score}/100</strong> · Sessions: ${r.sessions.length} · Findings: ${r.metrics.findings}</p><p>${esc(r.method)}</p><p>${esc(r.scoreMethod)}</p><small>Evidence SHA-256: ${r.evidenceSha256}<br>Scope: ${esc(r.hashScope)}</small><h2>Prioritized findings</h2>${r.findings.length?r.findings.map(f=>`<section><h3>${esc(f.severity)} · ${esc(f.title)}</h3><p>${esc(f.reason)}</p><p><strong>Remediation:</strong> ${esc(f.remediation)}</p><p>Sessions: ${f.sessions.join(', ')}</p></section>`).join(''):'<p>No configured rules triggered.</p>'}<h2>Session appendix</h2><table><thead><tr><th>ID</th><th>Endpoint</th><th>Protocol</th><th>TLS</th><th>Forward secrecy</th><th>Certificate</th><th>Score</th></tr></thead><tbody>${r.sessions.map(s=>`<tr><td>${s.id}</td><td>${s.server}</td><td>${s.protocol}</td><td>${s.tls}</td><td>${s.pfs}</td><td>${s.cert}</td><td>${s.issues.includes('partial')?'Unknown':scoreSession(s)}</td></tr>`).join('')}</tbody></table><h2>Limitations</h2><p>Synthetic demonstration. No trained machine-learning classifier, real TLS dissection, trust-store validation, or revocation checking. TLS 1.3 certificates are encrypted on the wire; shown fixture attributes are lab ground truth. A weak configuration does not establish endpoint compromise.</p></body></html>`;}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>go(el.dataset.nav));document.querySelectorAll('[data-session]').forEach(el=>el.onclick=e=>{e.stopPropagation();openSession(el.dataset.session);});document.querySelectorAll('[data-tls]').forEach(el=>el.onclick=()=>{state.page='Sessions';state.filter=el.dataset.tls;render();});document.querySelectorAll('[data-severity]').forEach(el=>el.onclick=()=>{state.filter=el.dataset.severity;render();});document.querySelectorAll('[data-scenario]').forEach(el=>el.onclick=()=>{state.selected=el.dataset.scenario;render();});document.querySelectorAll('[data-load]').forEach(el=>el.onclick=()=>{state.selected=el.dataset.load;runSimulation();});document.querySelectorAll('[data-fix]').forEach(el=>el.onclick=()=>{applyFix(el.dataset.fix);render();toast('Fix simulated. Posture and evidence have been recalculated.');});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));const search=document.getElementById('session-search');if(search)search.oninput=()=>{state.query=search.value;document.getElementById('session-rows').innerHTML=sessionRows();document.getElementById('result-count').textContent=filteredSessions().length+' matching sessions';document.querySelectorAll('[data-session]').forEach(el=>el.onclick=e=>{e.stopPropagation();openSession(el.dataset.session);});};const pf=document.getElementById('protocol-filter');if(pf)pf.onchange=()=>{state.protocol=pf.value;render();};const rf=document.getElementById('risk-filter');if(rf)rf.onchange=()=>{state.filter=rf.value;render();};const file=document.getElementById('capture-file');if(file)file.onchange=async()=>{const f=file.files[0];if(!f)return;try{if(f.size>50*1024*1024)throw Error('Capture exceeds the 50 MB demo limit.');file.disabled=true;const data=await f.arrayBuffer();const meta=inspectCapture(data);state.capture={'Filename':f.name,'Format':meta.format,'Packet records':meta.packets,'Size':`${meta.bytes.toLocaleString()} bytes`,'SHA-256':await hash(data),'Security posture':'Not assessed'};render();toast('Capture structure validated locally.');}catch(e){state.capture=null;render();toast(e.message);}};}
async function action(a){if(a==='run')return runSimulation();if(a==='reset'){if(state.busy)return;state.sessions=generateScenario(state.scenario);state.fixes=[];state.step=0;state.logs=[];render();toast('Original scenario restored.');}if(a==='clear-filters'){state.filter='All';state.protocol='All';state.query='';render();}if(a==='fix-all'){Object.keys(rules).filter(k=>rules[k].weight).forEach(applyFix);render();toast('All configuration fixes simulated. Partial captures remain unassessed.');}if(a==='score-info')showDrawer(`<div class="heading"><h1>How posture is scored</h1><button data-close aria-label="Close score explanation">${icon('close')}</button></div><p>Each complete session starts at 100. Triggered rule weights are subtracted and the result is clamped to zero. Overall posture is the rounded mean of assessed sessions.</p>${Object.values(rules).map(r=>`<div class="barlabel" style="margin:20px 0"><span>${r.title}</span><strong>${r.weight?'−'+r.weight:'Excluded'}</strong></div>`).join('')}<div class="notice">Incomplete handshake sessions are excluded from the overall score. This transparent demo score is not a validated risk model or a compliance certification.</div>`);if(['export-json','export-html','print'].includes(a)){let win;if(a==='print'){win=window.open('','_blank');if(!win){toast('Allow pop-ups to open the printable report.');return;}}try{const r=await report();if(a==='export-json')download(JSON.stringify(r,null,2),'securemailscope-report.json','application/json');else if(a==='export-html')download(reportHtml(r),'securemailscope-report.html','text/html');else{win.document.write(reportHtml(r));win.document.close();win.focus();}toast(a==='print'?'Report opened. Choose Print / Save as PDF.':'Report downloaded with evidence integrity hash.');}catch(e){win?.close();toast('Report export failed: '+e.message);}}}
if(document.modelContext){try{document.modelContext.registerTool({name:'load_security_scenario',description:'Load a synthetic SecureMailScope email security scenario.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(scenarios)}},required:['scenario']},execute:async({scenario})=>{if(!scenarios[scenario])throw Error('Unknown scenario');if(state.busy)throw Error('Wait for the current simulation');state.scenario=scenario;state.selected=scenario;state.sessions=generateScenario(scenario);state.fixes=[];go('Overview');return {content:[{type:'text',text:JSON.stringify(metrics(state.sessions))}]};}});}catch{}}
render();
